import {
  escapeHtmlAttribute,
  isBlankLine,
  isDigit,
  normalizeNewlines,
  trimSpaces,
} from './text.mjs';
import { renderInline } from './inline.mjs';

function getIndentStart(line) {
  let index = 0;

  while (index < line.length && index < 3 && line[index] === ' ') {
    index += 1;
  }

  return index;
}

function parseHeading(line) {
  const start = getIndentStart(line);
  let level = 0;
  let index = start;

  while (index < line.length && line[index] === '#') {
    level += 1;
    index += 1;
  }

  if (level === 0 || level > 6) {
    return null;
  }

  if (index < line.length && line[index] !== ' ') {
    return null;
  }

  while (index < line.length && line[index] === ' ') {
    index += 1;
  }

  return {
    level,
    text: trimSpaces(line.slice(index)),
  };
}

function parseOrderedItem(line) {
  const start = getIndentStart(line);
  let index = start;

  while (index < line.length && isDigit(line[index])) {
    index += 1;
  }

  if (index === start || index + 1 >= line.length || line[index] !== '.' || line[index + 1] !== ' ') {
    return null;
  }

  return {
    type: 'ol',
    text: line.slice(index + 2),
  };
}

function parseUnorderedItem(line) {
  const start = getIndentStart(line);

  if (start + 1 >= line.length) {
    return null;
  }

  const marker = line[start];

  if ((marker === '-' || marker === '*' || marker === '+') && line[start + 1] === ' ') {
    return {
      type: 'ul',
      text: line.slice(start + 2),
    };
  }

  return null;
}

function parseListItem(line) {
  return parseOrderedItem(line) ?? parseUnorderedItem(line);
}

function slugifyHeading(text) {
  let result = '';
  let previousWasDash = false;

  for (let index = 0; index < text.length; index += 1) {
    let character = text[index];

    if (character >= 'A' && character <= 'Z') {
      character = character.toLowerCase();
    }

    const isAsciiLetter = character >= 'a' && character <= 'z';
    const isAsciiDigit = character >= '0' && character <= '9';

    if (isAsciiLetter || isAsciiDigit) {
      result += character;
      previousWasDash = false;
      continue;
    }

    if (!previousWasDash && result.length > 0) {
      result += '-';
      previousWasDash = true;
    }
  }

  if (result.endsWith('-')) {
    result = result.slice(0, result.length - 1);
  }

  return result;
}

function renderHeading(heading, options) {
  const idAttribute = options.enableTocIds ? ` id="${escapeHtmlAttribute(slugifyHeading(heading.text))}"` : '';
  return `<h${heading.level}${idAttribute}>${renderInline(heading.text)}</h${heading.level}>`;
}

function renderList(lines, startIndex, firstItem) {
  const items = [firstItem.text];
  let index = startIndex + 1;

  while (index < lines.length) {
    if (isBlankLine(lines[index])) {
      break;
    }

    const nextItem = parseListItem(lines[index]);

    if (nextItem === null || nextItem.type !== firstItem.type) {
      break;
    }

    items.push(nextItem.text);
    index += 1;
  }

  const tagName = firstItem.type;
  const renderedItems = items.map((itemText) => `<li>${renderInline(itemText)}</li>`);
  return {
    html: `<${tagName}>\n${renderedItems.join('\n')}\n</${tagName}>`,
    nextIndex: index,
  };
}

function renderParagraph(lines, startIndex) {
  const collected = [];
  let index = startIndex;

  while (index < lines.length) {
    const line = lines[index];

    if (isBlankLine(line)) {
      break;
    }

    if (collected.length > 0) {
      const heading = parseHeading(line);
      const listItem = parseListItem(line);

      if (heading !== null || listItem !== null) {
